// MARK: - トピック会話 seed

/// Model-side row of a topic conversation. Built once from `TopicSeed`.
struct TopicLine: Identifiable, Hashable {
    let id: Int
    /// "A" or "B" — who is speaking.
    let speaker: String
    let english: String
    let japanese: String
}

struct TopicScene: Identifiable, Hashable {
    let id: Int
    /// Optional heading, e.g. 受付で. Empty for single-scene topics.
    let label: String
    let lines: [TopicLine]
}

struct TopicConversation: Identifiable, Hashable {
    let id: Int
    let emoji: String
    let title: String
    let category: String
    /// Handy expressions from the conversation, shown as chips.
    let keys: [String]
    let scenes: [TopicScene]

    var lineCount: Int { scenes.reduce(0) { $0 + $1.lines.count } }
}

/// Everyday conversations grouped by topic, each line carrying its Japanese
/// translation. Stored as tab-separated rows so the file stays compact, and
/// parsed once on first access.
enum TopicSeed {
    static let topics: [TopicConversation] = parse(raw)

    private static func parse(_ text: String) -> [TopicConversation] {
        var result: [TopicConversation] = []
        var emoji = "", title = "", category = "", keys: [String] = []
        var scenes: [TopicScene] = []
        var sceneLabel = ""
        var lines: [TopicLine] = []
        var lineId = 0, sceneId = 0

        func closeScene() {
            guard !lines.isEmpty else { return }
            sceneId += 1
            scenes.append(TopicScene(id: sceneId, label: sceneLabel, lines: lines))
            lines = []
        }
        func closeTopic() {
            closeScene()
            guard !title.isEmpty, !scenes.isEmpty else { return }
            result.append(
                TopicConversation(
                    id: result.count + 1,
                    emoji: emoji,
                    title: title,
                    category: category,
                    keys: keys,
                    scenes: scenes
                )
            )
            scenes = []
        }

        for line in text.split(separator: "\n", omittingEmptySubsequences: true) {
            let f = line.split(separator: "\t", omittingEmptySubsequences: false).map(String.init)
            switch f.first {
            case "T":
                guard f.count >= 5 else { continue }
                closeTopic()
                emoji = f[1]; title = f[2]; category = f[3]
                keys = f[4].split(separator: ",")
                    .map { $0.trimmingCharacters(in: .whitespaces) }
                    .filter { !$0.isEmpty }
                sceneLabel = ""
            case "S":
                closeScene()
                sceneLabel = f.count >= 2 ? f[1] : ""
            case "A", "B":
                guard f.count >= 3 else { continue }
                lineId += 1
                lines.append(
                    TopicLine(id: lineId, speaker: f[0], english: f[1], japanese: f[2])
                )
            default:
                continue
            }
        }
        closeTopic()
        return result
    }

    private static let raw = #"""
T	🚑	怪我をして救急に行く	健康	ER, get checked out, put weight on, swelling, fracture, elevated, that's a relief
S	
A	I think I need to go to the ER. I hurt my leg pretty badly.	救急に行ったほうがいいと思う。足をかなりひどく怪我しちゃった。
B	Oh, wow. What happened?	え、大丈夫？ どうしたの？
A	I slipped on the stairs and landed pretty hard on my knee.	階段で滑って、膝をかなり強く打ったんだ。
B	Can you walk?	歩ける？
A	Barely. It hurts a lot when I put weight on it.	なんとか。でも体重をかけるとかなり痛い。
B	Okay, let's get you checked out. Better to be safe.	じゃあ診てもらおう。念のため、そのほうがいいよ。
S	
A	Hi, I injured my knee, and I'm having a lot of pain.	すみません、膝を怪我して、かなり痛みがあります。
B	When did the injury happen?	いつ怪我をしましたか？
A	About an hour ago. I slipped and hit my knee on the stairs.	1時間くらい前です。滑って、階段に膝をぶつけました。
B	Are you able to walk?	歩くことはできますか？
A	Yes, but it's really painful.	はい、でもかなり痛いです。
B	Have you noticed any swelling or bleeding?	腫れや出血はありますか？
